function living(pic: string, what: Pair, alive: boolean, nudge: Pair, first: Pair, why: Pair, alt?: Pair): Entry {
  return {
    q: [`Is ${what[0]} living or not living?`, `¿${cap(what[1])} es un ser vivo o no vivo?`],
    pic,
    alt: alt ?? [cap(what[0]), cap(what[1])],
    a: alive ? [LIVING, NOT_LIVING] : [NOT_LIVING, LIVING],
    h: [nudge, first],
    s: [why],
  };
}

function matter(pic: string, what: Pair, key: Option, nudge: Pair, first: Pair, why: Pair): Entry {
  return {
    q: [`${cap(what[0])}. Is it a solid, a liquid or a gas?`, `${cap(what[1])}. ¿Es un sólido, un líquido o un gas?`],
    pic,
    alt: [cap(what[0]), cap(what[1])],
    a: [key, ...[SOLID, LIQUID, GAS].filter((c) => c !== key)],
    h: [nudge, first],
    s: [why],
  };
}

