// Metric conversion (computed). Amounts are built from an integer count of the smaller unit, so the
// larger-unit amount is that integer shifted by a power of ten and written exactly with `dec`.

type Unit = { sym: string; en: [string, string]; es: [string, string] };
const unit = (sym: string, en: string, es: string): Unit => ({ sym, en: [en, `${en}s`], es: [es, `${es}s`] });
const MM = unit("mm", "millimeter", "milímetro");
const CM = unit("cm", "centimeter", "centímetro");
const M = unit("m", "meter", "metro");
const KM = unit("km", "kilometer", "kilómetro");
const G = unit("g", "gram", "gramo");
const KG = unit("kg", "kilogram", "kilogramo");
const ML = unit("mL", "milliliter", "mililitro");
const LITER = unit("L", "liter", "litro");

/** small × 10^k = big. kind: 0 length, 1 mass, 2 volume. */
type Conv = { small: Unit; big: Unit; k: 1 | 2 | 3; kind: 0 | 1 | 2 };
const L1_CONV: Conv[] = [
  { small: CM, big: M, k: 2, kind: 0 },
  { small: G, big: KG, k: 3, kind: 1 },
  { small: ML, big: LITER, k: 3, kind: 2 },
];
const L2_LENGTH: Conv[] = [
  { small: MM, big: CM, k: 1, kind: 0 },
  { small: CM, big: M, k: 2, kind: 0 },
  { small: MM, big: M, k: 3, kind: 0 },
  { small: M, big: KM, k: 3, kind: 0 },
];
const L2_OTHER: Conv[] = [
  { small: G, big: KG, k: 3, kind: 1 },
  { small: ML, big: LITER, k: 3, kind: 2 },
];

/** n ÷ 10^k written exactly, without trailing zeros: dec(275, 2) = "2.75", dec(50, 3) = "0.05". */
function dec(n: number, k: number) {
  const s = String(n).padStart(k + 1, "0");
  const frac = s.slice(-k).replace(/0+$/, "");
  return frac ? `${s.slice(0, -k)}.${frac}` : s.slice(0, -k);
}

const DECIMAL_KEY: ItemBody["keys"] = ["."];
const ZEROS_EN = ["", "one", "two", "three"];
const ZEROS_ES = ["", "un", "dos", "tres"];

function convert(r: Rng, level: number, locale: Locale): ItemBody {
  const c = level === 1 ? r.pick(L1_CONV) : r.bool(0.7) ? r.pick(L2_LENGTH) : r.pick(L2_OTHER);
  const { small, big, k } = c;
  const f = 10 ** k;
  // `n` is the amount in the smaller unit; at level 2 it never divides evenly, so a decimal appears.
  let n = level === 1 ? r.int(2, 12) * f : 0;
  while (level === 2 && n % f === 0) n = k === 3 ? 10 * r.int(5, 999) : k === 2 ? r.int(15, 999) : r.int(11, 199);
  const amount = dec(n, k);
  const toBig = r.bool();
  const whole = Math.floor(n / f), rest = n % f;
  const name = (u: Unit, value: string) => tr(locale, u.en[value === "1" ? 0 : 1], u.es[value === "1" ? 0 : 1]);
  const [from, to, shown, want] = toBig ? [small, big, String(n), amount] : [big, small, amount, String(n)];
  const zerosEn = `${ZEROS_EN[k]} ${k === 1 ? "zero" : "zeros"}`, zerosEs = `${ZEROS_ES[k]} ${k === 1 ? "cero" : "ceros"}`;
  const placesEn = `${ZEROS_EN[k]} ${k === 1 ? "place" : "places"}`, placesEs = `${ZEROS_ES[k]} ${k === 1 ? "lugar" : "lugares"}`;
  const bigger = [
    [`A ${big.en[0]} is longer than a ${small.en[0]}`, `Un ${big.es[0]} es más largo que un ${small.es[0]}`],
    [`A ${big.en[0]} is heavier than a ${small.en[0]}`, `Un ${big.es[0]} es más pesado que un ${small.es[0]}`],
    [`A ${big.en[0]} holds more than a ${small.en[0]}`, `Un ${big.es[0]} contiene más que un ${small.es[0]}`],
  ][c.kind];
  const strategy = toBig
    ? tr(locale, `${f} ${small.sym} = 1 ${big.sym}, so divide by ${f}.`, `${f} ${small.sym} = 1 ${big.sym}, así que divide entre ${f}.`) +
      (level === 2 ? tr(locale, ` Dividing by ${f} moves the decimal point ${placesEn} to the left.`, ` Dividir entre ${f} mueve el punto decimal ${placesEs} a la izquierda.`) : "")
    : tr(locale, `1 ${big.sym} = ${f} ${small.sym}, so multiply by ${f}.`, `1 ${big.sym} = ${f} ${small.sym}, así que multiplica por ${f}.`) +
      (level === 2 ? tr(locale, ` Multiplying by ${f} moves the decimal point ${placesEn} to the right.`, ` Multiplicar por ${f} mueve el punto decimal ${placesEs} a la derecha.`) : "");
  let first: string;
  if (level === 1) {
    first = toBig
      ? tr(locale, `${n} ÷ ${f}: take ${zerosEn} off the end of ${n}.`, `${n} ÷ ${f}: quita ${zerosEs} del final de ${n}.`)
      : tr(locale, `${amount} × ${f}: write ${zerosEn} after ${amount}.`, `${amount} × ${f}: escribe ${zerosEs} después de ${amount}.`);
  } else if (toBig) {
    first = whole
      ? tr(locale, `${n} ${small.sym} = ${whole * f} ${small.sym} + ${rest} ${small.sym}, and ${whole * f} ${small.sym} = ${whole} ${big.sym}.`, `${n} ${small.sym} = ${whole * f} ${small.sym} + ${rest} ${small.sym}, y ${whole * f} ${small.sym} = ${whole} ${big.sym}.`)
      : tr(locale, `${n} ${small.sym} is less than ${f} ${small.sym}, so the answer is less than 1.`, `${n} ${small.sym} es menos de ${f} ${small.sym}, así que la respuesta es menor que 1.`);
  } else {
    first = whole
      ? tr(locale, `${whole} ${big.sym} = ${whole * f} ${small.sym}. Now convert the other ${dec(rest, k)} ${big.sym}.`, `${whole} ${big.sym} = ${whole * f} ${small.sym}. Ahora convierte los otros ${dec(rest, k)} ${big.sym}.`)
      : tr(locale, `${amount} ${big.sym} is less than 1 ${big.sym}, so the answer is less than ${f}.`, `${amount} ${big.sym} es menos de 1 ${big.sym}, así que la respuesta es menor que ${f}.`);
  }
  return {
    prompt: [`${shown} ${from.sym} = `, { blank: true }, ` ${to.sym}`],
    say: tr(locale, `${shown} ${name(from, shown)} is how many ${to.en[1]}?`, `¿Cuántos ${to.es[1]} son ${shown} ${name(from, shown)}?`),
    input: "keypad",
    ...(level === 2 ? { keys: DECIMAL_KEY } : {}),
    answer: { kind: "number", value: Number(want) },
    hints: [
      tr(locale, `${bigger[0]}, so you will need ${toBig ? `fewer ${big.en[1]}` : `more ${small.en[1]}`}.`, `${bigger[1]}, así que necesitarás ${toBig ? `menos ${big.es[1]}` : `más ${small.es[1]}`}.`),
      strategy,
      first,
    ],
    steps: toBig
      ? [`${f} ${small.sym} = 1 ${big.sym}`, `${n} ÷ ${f} = ${amount}`, `${n} ${small.sym} = ${amount} ${big.sym}`]
      : [`1 ${big.sym} = ${f} ${small.sym}`, `${amount} × ${f} = ${n}`, `${amount} ${big.sym} = ${n} ${small.sym}`],
    seconds: level === 1 ? 15 : 30,
  };
}

const fromBanks = (id: string) => (r: Rng, level: number, locale: Locale) => fromBank(r, BANKS[id][level - 1], locale);

